//
//  MacClipboardWatcher.swift
//  ConduitCore
//
//  Notices when something is copied on this Mac, to send it to the phone.
//
//  macOS has no notification for a copy, so the change count is checked
//  twice a second — that reads nothing. Reading the text itself is what
//  macOS guards: by default it asks the person on every read an app makes
//  by itself. So Conduit reads automatically only once the person has set
//  it to Always Allow, and otherwise says how instead of popping an alert
//  on every copy.
//
//  Text a password manager marks as concealed, transient or auto-generated
//  (the nspasteboard.org conventions) is never read at all.
//

import AppKit
import ConduitState

@MainActor
final class MacClipboardWatcher {

    /// Large enough for any paragraph, small enough for one control frame.
    static let maximumBytes = 256 * 1024

    private static let markedPrivate: Set<NSPasteboard.PasteboardType> = [
        NSPasteboard.PasteboardType("org.nspasteboard.ConcealedType"),
        NSPasteboard.PasteboardType("org.nspasteboard.TransientType"),
        NSPasteboard.PasteboardType("org.nspasteboard.AutoGeneratedType"),
    ]

    /// Something new was copied on this Mac.
    var onCopy: (String) -> Void = { _ in }

    private var lastChange = NSPasteboard.general.changeCount
    private var timer: Timer?

    func start() {
        guard timer == nil else { return }
        lastChange = NSPasteboard.general.changeCount
        timer = Timer.scheduledTimer(withTimeInterval: 0.5, repeats: true) { [weak self] _ in
            MainActor.assumeIsolated { self?.check() }
        }
    }

    func stop() {
        timer?.invalidate()
        timer = nil
    }

    /// Conduit just wrote the clipboard itself — text from the phone. That
    /// change is not a copy to send back.
    func noteOwnWrite() {
        lastChange = NSPasteboard.general.changeCount
    }

    /// Whether macOS lets Conduit read the clipboard without asking.
    static var access: MacClipboardAccess {
        if #available(macOS 15.4, *) {
            switch NSPasteboard.general.accessBehavior {
            case .alwaysAllow: return .allowed
            case .alwaysDeny: return .denied
            default: return .asks
            }
        }
        return .allowed
    }

    /// The text on the clipboard, unless macOS would have to ask first or a
    /// password manager marked it private. `asking` is for the person's own
    /// click, where macOS's question is expected.
    static func readText(asking: Bool = false) -> String? {
        guard asking || access == .allowed else { return nil }
        let pasteboard = NSPasteboard.general
        if let types = pasteboard.types, !markedPrivate.isDisjoint(with: types) { return nil }
        guard let text = pasteboard.string(forType: .string), !text.isEmpty,
              text.utf8.count <= maximumBytes else { return nil }
        return text
    }

    private func check() {
        let count = NSPasteboard.general.changeCount
        guard count != lastChange else { return }
        lastChange = count
        guard let text = Self.readText() else { return }
        onCopy(text)
    }
}
